+/**
+ * Sanitize an SVG element to prevent XSS attacks.
+ * Removes script elements, event handlers, and javascript: URLs.
+ * @param {SVGSVGElement} svg - The SVG element to sanitize.
+ */
+const sanitizeSVG = function (svg) {
+    if (!svg || typeof svg.querySelectorAll !== 'function') {
+        return;
+    }
+
+    // Remove script elements
+    const scripts = svg.querySelectorAll('script');
+    for (let i = 0; i < scripts.length; i++) {
+        scripts[i].parentNode.removeChild(scripts[i]);
+    }
+
+    // Remove foreignObject elements (can contain arbitrary HTML)
+    const foreignObjects = svg.querySelectorAll('foreignObject');
+    for (let i = 0; i < foreignObjects.length; i++) {
+        foreignObjects[i].parentNode.removeChild(foreignObjects[i]);
+    }
+
+    // Remove event handler attributes and javascript: URLs from all elements
+    const allElements = svg.querySelectorAll('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const el = allElements[i];
+        const attrs = el.attributes;
+        if (!attrs) continue;
+
+        const toRemove = [];
+        for (let j = 0; j < attrs.length; j++) {
+            const attrName = attrs[j].name.toLowerCase();
+            const attrValue = attrs[j].value || '';
+
+            // Remove event handlers (on*)
+            if (attrName.substring(0, 2) === 'on') {
+                toRemove.push(attrs[j].name);
+            }
+
+            // Remove javascript: URLs from href and xlink:href attributes
+            if ((attrName === 'href' || attrName === 'xlink:href') &&
+                attrValue.trim().substring(0, 11).toLowerCase() === 'javascript:') {
+                toRemove.push(attrs[j].name);
+            }
+
+            // Remove data: URLs that could contain scripts
+            if ((attrName === 'href' || attrName === 'xlink:href') &&
+                attrValue.trim().substring(0, 5).toLowerCase() === 'data:') {
+                toRemove.push(attrs[j].name);
+            }
+        }
+
+        for (let j = 0; j < toRemove.length; j++) {
+            el.removeAttribute(toRemove[j]);
+        }
+    }
+};
+
+module.exports = sanitizeSVG;
